<style>
.growth-card{margin:24px 0;border:1px solid var(--border,#e2e8f0);border-radius:24px;overflow:hidden;background:var(--card-bg,var(--bg-card,#fff));box-shadow:0 8px 24px #18274a08;color:var(--text-primary,#18213a)}
.growth-head{padding:24px;display:flex;justify-content:space-between;gap:18px;align-items:center;background:linear-gradient(115deg,#486aff14,#9255ef10,#17bfa90b);border-bottom:1px solid var(--border,#e2e8f0)}
.growth-label{font-size:10px;font-weight:800;letter-spacing:.14em;color:var(--accent,#5367e9)}.growth-head h2{font-size:24px;font-weight:750;margin:8px 0}.growth-head p,.growth-foot,.growth-meta{font-size:12px;color:var(--text-muted,#68738a)}.growth-badge{font-size:11px;border:1px solid #6876eb30;border-radius:20px;padding:8px 12px;white-space:nowrap}.growth-body{padding:24px}.growth-context summary{cursor:pointer;font-weight:600}.growth-context summary span{font-size:12px;font-weight:400;color:var(--text-muted,#68738a);margin-left:8px}.growth-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:18px 0}.growth-fields label{font-size:12px}.growth-fields input{display:block;width:100%;margin-top:7px}.growth-controls,.growth-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0;font-size:12px}.growth-controls label{display:flex;align-items:center;gap:8px}.growth-controls span{color:var(--text-muted,#68738a)}.growth-primary{background:linear-gradient(110deg,#3659ed,#7050e9);color:white;border:0;border-radius:12px;padding:11px 16px;font-size:12px;font-weight:600}.growth-primary:disabled{opacity:.5;cursor:wait}.growth-quiet{background:transparent;border:0;padding:0;font-size:12px;color:var(--accent,#5367e9);margin-top:8px}.growth-status{font-size:13px;overflow-wrap:anywhere}.growth-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.growth-tabs button{background:transparent;color:inherit;border:1px solid var(--border,#e2e8f0);border-radius:12px;padding:8px 12px;font-size:12px}.growth-tabs button[aria-pressed=true]{background:#5666ee18;border-color:#6a74ec;color:var(--accent,#5367e9)}.growth-result{font-size:14px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.growth-result ol{padding-left:22px}.growth-result li{margin:10px 0}.growth-result a{color:var(--accent,#5367e9)}.growth-followup{margin-top:20px;font-size:12px}.growth-followup>div{display:flex;gap:10px;margin-top:7px}.growth-followup input{flex:1;min-width:0}.growth-foot{margin:20px 0 0}.growth-card [hidden]{display:none!important}@media(max-width:700px){.growth-head{align-items:flex-start;flex-direction:column}.growth-fields{grid-template-columns:1fr}.growth-body,.growth-head{padding:18px}.growth-followup>div{flex-direction:column}}
</style>
<script>
(()=>{
const root=document.getElementById('ai-growth');if(!root)return;
const scope=@json($growthScope),urls={state:@json(route('user.growth.state')),estimate:@json(route('user.growth.estimate')),generate:@json(route('user.growth.generate'))},csrf=@json(csrf_token());
const el=s=>root.querySelector(s),status=el('[data-status]'),cost=el('[data-cost]');let report=null,quote=null,tab='overview',busy=false;
const draftKey='sayzio:growth:'+@json(auth()->id())+':'+@json(app()->bound('current_workspace') ? app('current_workspace')?->id : 0)+':'+JSON.stringify(scope);
const context=()=>Object.fromEntries([...root.querySelectorAll('[data-context]')].map(i=>[i.dataset.context,i.value]));
function invalidate(){try{localStorage.setItem(draftKey,JSON.stringify(context()))}catch{}quote=null;el('[data-generate]').hidden=true;cost.textContent='Estimate again after changing context or research.';}
root.querySelectorAll('[data-context],[data-research],#growth-question').forEach(i=>i.addEventListener('input',invalidate));
async function call(action,body){const url=new URL(urls[action],location.origin);let opts={headers:{Accept:'application/json','X-CSRF-TOKEN':csrf}};if(action==='state'){Object.entries(scope).forEach(([k,v])=>{if(v===null||v===undefined)return;Array.isArray(v)?v.forEach(x=>url.searchParams.append(k+'[]',x)):url.searchParams.set(k,v)});}else{opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}const resp=await fetch(url,opts);const data=await resp.json().catch(()=>({message:'Unable to load insights.'}));if(!resp.ok)throw Error(data.message||'Unable to load insights.');return data;}
function render(){if(!report)return;el('.growth-followup').hidden=tab!=='answer';const box=el('[data-result]');box.replaceChildren();const value=report[tab];if(Array.isArray(value)){if(!value.length)box.textContent=tab==='market'?'Market research was not included in this report.':'No additional findings.';else{const ol=document.createElement('ol');value.forEach(text=>{const li=document.createElement('li');li.textContent=text;ol.append(li)});box.append(ol)}}else box.textContent=value||(tab==='answer'?'Ask a follow-up below. A new estimate is shown before each answer.':'No findings.');if(tab==='market'){(report.sources||[]).forEach(s=>{try{const u=new URL(s.url);if(!['https:','http:'].includes(u.protocol))return;const p=document.createElement('p'),a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent='['+s.id+'] '+s.title;p.append(a,document.createTextNode(' · retrieved '+new Date(s.retrieved_at).toLocaleDateString()));box.append(p)}catch{}});if(report.sources?.length){const p=document.createElement('p');p.textContent='Based on search snippets; publication dates and full pages have not been verified.';box.append(p)}}root.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));}
function show(data){report=data.report;el('.growth-context').open=false;el('[data-report]').hidden=false;el('[data-meta]').textContent='Saved '+new Date(data.created_at).toLocaleString()+' · '+data.coins_spent+' coins used · '+report.range.join(' – ')+(data.changed?' · Analytics changed — generate a fresh report.':'')+(report.limited_data?' · Limited sample: interpret suggestions cautiously.':'');el('[data-suggest]').hidden=!Object.values(report.suggested_context||{}).some(Boolean);render();}
root.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;render()}));
el('[data-suggest]').addEventListener('click',()=>{root.querySelectorAll('[data-context]').forEach(i=>{if(report?.suggested_context?.[i.dataset.context])i.value=report.suggested_context[i.dataset.context]});invalidate()});
async function run(action,question=''){if(busy)return;busy=true;root.querySelectorAll('.growth-primary').forEach(b=>b.disabled=true);status.textContent=action==='estimate'?'Calculating coin estimate…':'Generating insights…';try{if(action==='estimate'){quote=await call(action,{...scope,context:context(),research:el('[data-research]').checked,question});cost.textContent='Estimated up to '+quote.estimated_coins+' coins (includes fallback budget) · Balance '+quote.balance+' · Estimate valid for 10 minutes';el('[data-generate]').textContent=question?'Generate answer':'Generate report';el('[data-generate]').hidden=false;status.textContent='Review the estimate, then generate when ready.';}else{if(!quote)throw Error('Request an estimate first.');const data=await call(action,{token:quote.token});show(data);tab=data.report.question?'answer':'overview';render();quote=null;el('[data-generate]').hidden=true;cost.textContent=data.coins_spent+' coins used. Saved report is free to reopen.';status.textContent='Insights saved.';}}catch(e){status.textContent=e.message;}finally{busy=false;root.querySelectorAll('.growth-primary').forEach(b=>b.disabled=false)}}
el('[data-estimate]').addEventListener('click',()=>run('estimate'));el('[data-generate]').addEventListener('click',()=>run('generate'));el('[data-ask]').addEventListener('click',()=>{const q=el('#growth-question').value.trim();if(!q){status.textContent='Enter a follow-up question.';return}run('estimate',q)});
call('state').then(data=>{let draft={};try{draft=JSON.parse(localStorage.getItem(draftKey)||'{}')||{}}catch{}root.querySelectorAll('[data-context]').forEach(i=>i.value=draft[i.dataset.context]||data.context?.[i.dataset.context]||'');el('[data-research]').disabled=!data.research_enabled;el('[data-research-note]').textContent=data.research_enabled?'Adds sourced market opportunities; included in your estimate.':'Disabled: search API key or Search Engine ID is missing. Admin → Integrations → Google Custom Search.';if(data.latest)show(data.latest);status.textContent=data.enabled?(data.latest?'Saved report loaded.':'Add your context and request an estimate.'):'AI is currently disabled by the administrator.';el('[data-estimate]').disabled=!data.enabled;el('[data-ask]').disabled=!data.enabled;}).catch(e=>status.textContent=e.message);
})();
</script>
